<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Manage appointment</title><style>body{font-family:system-ui;background:#f1f5f9;color:#0f172a;margin:0}.wrap{max-width:560px;margin:50px auto;padding:16px}.card{background:#fff;padding:28px;border-radius:16px;box-shadow:0 10px 30px #0f172a14}.muted{color:#64748b}.ok{background:#ecfdf5;color:#065f46;padding:12px;border-radius:10px}.err{background:#fef2f2;color:#991b1b;padding:12px;border-radius:10px}.btn{display:inline-block;border:0;border-radius:9px;padding:10px 14px;background:#0f766e;color:#fff;text-decoration:none;font-weight:600;cursor:pointer}.danger{background:#dc2626}input{width:100%;padding:10px;border:1px solid #cbd5e1;border-radius:8px;box-sizing:border-box}.slots{display:flex;flex-wrap:wrap;gap:7px}.slot{border:1px solid #cbd5e1;background:#fff;padding:8px;border-radius:8px;cursor:pointer}.slot.on{background:#0f766e;color:#fff}</style></head><body><main class="wrap"><div class="card"><h1>Manage appointment</h1>@if(session('success'))<p class="ok">{{ session('success') }}</p>@endif @if($errors->any())<div class="err">{{ $errors->first() }}</div>@endif<p><strong>{{ $appointment->service?->name }}</strong><br>{{ $appointment->starts_at->timezone($appointment->site?->timezone ?: 'UTC')->format('D, M j Y · g:i A') }}<br><span class="muted">{{ $appointment->site?->timezone }}</span></p>@if($appointment->service?->location_details)<p><strong>Location:</strong> {{ $appointment->service->location_details }}</p>@endif<p>Status: <strong>{{ $appointment->statusLabel() }}</strong></p>@if($appointment->status === \App\Models\BookingAppointment::STATUS_PENDING_PAYMENT)<p><strong>Amount due:</strong> {{ $appointment->currency }} {{ number_format($appointment->amount_cents/100,2) }}</p><form method="POST" action="{{ url('/b/'.$appointment->site->public_key.'/manage/'.$appointment->confirmation_code.'/payment') }}">@csrf<button class="btn">Continue payment</button></form>@endif @if($appointment->status === \App\Models\BookingAppointment::STATUS_SCHEDULED)<a class="btn" href="{{ url('/b/'.$appointment->site->public_key.'/manage/'.$appointment->confirmation_code.'/calendar.ics') }}">Add to calendar</a><hr><h3>Reschedule</h3><input type="date" id="new-date" min="{{ now($appointment->site->timezone)->toDateString() }}"><div id="new-slots" class="slots"></div><form method="POST" action="{{ url('/b/'.$appointment->site->public_key.'/manage/'.$appointment->confirmation_code.'/reschedule') }}" id="reschedule-form">@csrf<input type="hidden" name="starts_at" id="new-start"><button class="btn" id="reschedule-btn" disabled>Confirm new time</button></form><script>document.getElementById('new-date').addEventListener('change',async function(){const box=document.getElementById('new-slots'),start=document.getElementById('new-start'),button=document.getElementById('reschedule-btn');start.value='';button.disabled=true;box.textContent='Loading…';const response=await fetch(@json(url('/b/'.$appointment->site->public_key.'/slots')).'?service_id={{ $appointment->booking_service_id }}&date='+encodeURIComponent(this.value),{headers:{Accept:'application/json'}});const data=await response.json();box.innerHTML='';(data.slots||[]).forEach(iso=>{const b=document.createElement('button');b.type='button';b.className='slot';b.textContent=new Date(iso).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'});b.onclick=()=>{box.querySelectorAll('.slot').forEach(x=>x.classList.remove('on'));b.classList.add('on');start.value=iso;button.disabled=false};box.appendChild(b)});if(!(data.slots||[]).length)box.textContent='No times available.'});</script>@endif @if(in_array($appointment->status,[\App\Models\BookingAppointment::STATUS_SCHEDULED,\App\Models\BookingAppointment::STATUS_PENDING_PAYMENT],true))<hr><form method="POST" action="{{ url('/b/'.$appointment->site->public_key.'/manage/'.$appointment->confirmation_code.'/cancel') }}">@csrf<label for="reason">Cancellation reason (optional)</label><input id="reason" name="reason" maxlength="255"><button class="btn danger" style="margin-top:12px" onclick="return confirm('Cancel this appointment?')">Cancel appointment</button></form>@endif</div></main></body></html>
